		});

		it("follows a logical expression into an uppercase variable", () => {
			expect(isDefault("var Foo = function () {} || null;")).toBe(false);
		});

		it("follows a conditional expression into an object property", () => {
			expect(
				isDefault("var obj = { foo: cond ? function () {} : null };"),
			).toBe(false);
		});

		it("follows a conditional expression into a lowercase variable", () => {
			expect(isDefault("var foo = cond ? function () {} : bar;")).toBe(
				true,
			);
		});

		it("follows a conditional expression into an uppercase variable", () => {
			expect(isDefault("var Foo = cond ? function () {} : bar;")).toBe(
				false,
			);
		});

		it("treats an optional member access without a call as a default binding", () => {
			expect(isDefault("var foo = (function () {})?.name;")).toBe(true);
		});

		it("keeps optional member access property reads as default bindings for uppercase variables", () => {
			// Optional member access is not a `bind`/`call`/`apply` usage.
			expect(isDefault("var Foo = (function () {})?.name;")).toBe(true);
		});

