			expect(
				canTokensBeAdjacent(
					token("Numeric", "1"),
					token("Numeric", ".5"),
				),
			).toBe(false);
		});

		test("rejects a numeric token that does not start with a dot", () => {
			expect(
				canTokensBeAdjacent(
					token("Identifier", "value"),
					token("Numeric", "5"),
				),
