		test("allows block comments on either side", () => {
			expect(
				canTokensBeAdjacent(
					token("Identifier", "left"),
					token("Block", " comment "),
				),
			).toBe(true);
			expect(
				canTokensBeAdjacent(
					token("Block", " comment "),
