			expect(
				canTokensBeAdjacent(
					token("Identifier", "left"),
					token("Line", " comment"),
				),
			).toBe(true);
			expect(
				canTokensBeAdjacent(
					token("Line", " comment"),
					token("Identifier", "right"),
				),
			).toBe(false);
		});

		test("allows a private identifier on the right", () => {
			expect(
				canTokensBeAdjacent(
					token("Identifier", "object"),
					token("PrivateIdentifier", "#field"),
				),
