		it("returns false for compound assignments that are not logical", () => {
			expect(check("value += 1", false)).toBe(false);
			expect(check("value += 1", true)).toBe(false);
		});

		it("returns true for logical assignments whose right side is an identity element in a boolean position", () => {
			expect(check("value ||= true", true)).toBe(true);
			expect(check("value &&= 0", true)).toBe(true);
		});

		it("returns false for logical assignments that are not identity elements", () => {
			expect(check("value ||= false", true)).toBe(false);
			expect(check("value &&= 1", true)).toBe(false);
		});

		it("returns false for logical assignments outside a boolean position", () => {
			expect(check("value ||= true", false)).toBe(false);
			expect(check("value &&= 0", false)).toBe(false);
		});

		it("returns false for nullish logical assignments", () => {
			expect(check("value ??= 1", true)).toBe(false);
		});
	});

	describe("SequenceExpression", () => {
		it("uses the last expression of the sequence", () => {
			expect(check("(other, 1)", false)).toBe(true);
			expect(check("(1, other)", false)).toBe(false);
		});

		it("passes the boolean position down to the last expression", () => {
			expect(check("(other, [item])", true)).toBe(true);
			expect(check("(other, [item])", false)).toBe(false);
		});
	});

	describe("SpreadElement", () => {
		it("checks the spread argument using the current boolean position", () => {
			const constantSpread = parseExpression("[...'abc']").elements[0];
			const unknownSpread = parseExpression("[...items]").elements[0];
			const scope = createScope();

			expect(constantSpread.type).toBe("SpreadElement");
			expect(unknownSpread.type).toBe("SpreadElement");
			expect(isConstant(scope, constantSpread, false)).toBe(true);
			expect(isConstant(scope, unknownSpread, false)).toBe(false);
			expect(isConstant(scope, unknownSpread, true)).toBe(false);
		});
	});

	describe("CallExpression", () => {
		it("returns true for a global `Boolean()` call with no arguments", () => {
			const node = parseExpression("Boolean()");
			const scope = createScope({ globals: [node.callee] });

			expect(isConstant(scope, node, true)).toBe(true);
			expect(isConstant(scope, node, false)).toBe(true);
		});

		it("returns true for a global `Boolean(<constant>)` call", () => {
			const node = parseExpression("Boolean(1)");
			const scope = createScope({ globals: [node.callee] });

			expect(isConstant(scope, node, true)).toBe(true);
		});

		it("returns true for a global `Boolean(<constant in boolean position>)` call", () => {
			const node = parseExpression("Boolean([item])");
			const scope = createScope({ globals: [node.callee] });

			expect(isConstant(scope, node, true)).toBe(true);
		});

		it("returns true for a global `Boolean(<global undefined>)` call", () => {
			const node = parseExpression("Boolean(undefined)");
			const scope = createScope({
				globals: [node.callee, identifierNamed(node, "undefined")],
			});

			expect(isConstant(scope, node, true)).toBe(true);
		});

		it("returns false when the argument is not constant", () => {
			const node = parseExpression("Boolean(value)");
			const scope = createScope({ globals: [node.callee] });

			expect(isConstant(scope, node, true)).toBe(false);
		});

		it("returns false when `Boolean` is shadowed by a local binding", () => {
			const node = parseExpression("Boolean(1)");
			const scope = createScope({ locals: [node.callee] });

			expect(isConstant(scope, node, true)).toBe(false);
		});

		it("returns false when `Boolean` has no matching reference in the scope", () => {
			const node = parseExpression("Boolean(1)");

			expect(isConstant(createScope(), node, true)).toBe(false);
		});

		it("returns false for calls to other functions", () => {
			const node = parseExpression("Number(1)");
			const scope = createScope({ globals: [node.callee] });

			expect(isConstant(scope, node, true)).toBe(false);
		});

		it("returns false for member calls named Boolean", () => {
			const node = parseExpression("globalThis.Boolean(1)");
			const scope = createScope({ globals: identifiersOf(node) });

			expect(isConstant(scope, node, true)).toBe(false);
		});
	});

	describe("Identifier", () => {
		it("returns true for `undefined` that resolves to a global variable", () => {
			const node = parseExpression("undefined");
			const scope = createScope({ globals: [node] });

			expect(isConstant(scope, node, false)).toBe(true);
			expect(isConstant(scope, node, true)).toBe(true);
		});

		it("returns false for a local `undefined`", () => {
			const node = parseExpression("undefined");
			const scope = createScope({ locals: [node] });

			expect(isConstant(scope, node, true)).toBe(false);
		});

		it("returns false for `undefined` with no matching reference", () => {
			const node = parseExpression("undefined");

			expect(isConstant(createScope(), node, true)).toBe(false);
		});

		it("returns false for other identifiers even when they are global", () => {
			const node = parseExpression("someGlobal");
			const scope = createScope({ globals: [node] });

			expect(isConstant(scope, node, true)).toBe(false);
		});
	});

	describe("unsupported node types", () => {
		it.each([
			["this", "this"],
			["member expression", "object.property"],
			["conditional expression", "test ? 1 : 2"],
			["chain expression", "object?.property"],
			["tagged template", "tag`text`"],
		])("returns false for a %s", (description, code) => {
			expect(check(code, false)).toBe(false);
			expect(check(code, true)).toBe(false);
		});
	});

	describe("nested expressions", () => {
		it("returns true for deeply nested constant collections", () => {
			expect(check("[1, ['two', [3]]]", false)).toBe(true);
		});

		it("returns false when a deeply nested value is not constant", () => {
			expect(check("[1, ['two', [value]]]", false)).toBe(false);
		});

		it("combines logical and assignment handling", () => {
			expect(check("(value &&= 0) && other", true)).toBe(true);
			expect(check("(value &&= 0) && other", false)).toBe(false);
		});

		it("handles binary expressions inside boolean positions", () => {
			expect(check("!([1] === 2)", true)).toBe(true);
			expect(check("!(value === other)", true)).toBe(false);
		});
	});
});
